    """Truncate text to n characters at word boundary, appending '…'."""
    if len(text) <= n:
        return text
    truncated = text[:n].rstrip()
    last_space = truncated.rfind(' ')
    if last_space > 0:
        truncated = truncated[:last_space]
    return truncated + '…'

